// one data channel message can be at most 256KB in chrome (and a big autodisk block is bigger), so a big message
// goes out in pieces. the channel is ordered, every piece starts with one byte, MORE if another piece of the same
// message follows. hyper-webrtc gives every data channel message to protomux as one whole message, so the
// receiving side joins the pieces again. the page (forwarding) and the worker (transferred channel) both use this
const CHUNK = 16 * 1024 // the message size every browser accepts
const MORE = 1
const LAST = 0

module.exports = { split, make_joiner }

function split (data) {
  const pieces = []
  let i = 0
  do {
    const piece = new Uint8Array(Math.min(CHUNK, data.byteLength - i) + 1)
    piece[0] = i + CHUNK < data.byteLength ? MORE : LAST
    piece.set(data.subarray(i, i + CHUNK), 1)
    pieces.push(piece)
    i += CHUNK
  } while (i < data.byteLength)
  return pieces
}

// on_message gets every whole message once its last piece came
function make_joiner (on_message) {
  let parts = []
  return function on_piece (piece) {
    parts.push(piece.subarray(1))
    if (piece[0] === MORE) return
    const data = parts.length === 1 ? parts[0] : join(parts)
    parts = []
    on_message(data)
  }
}

function join (parts) {
  const data = new Uint8Array(parts.reduce((size, part) => size + part.byteLength, 0))
  let at = 0
  for (const part of parts) { data.set(part, at); at += part.byteLength }
  return data
}
